import itertools
import random

def has_cycle_of_length_at_most(edges, n, max_len):
    """Check if graph has a cycle of length <= max_len"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS/DFS to find cycles
    for start in range(n):
        # simple DFS limited depth
        stack = [(start, -1, [start])]
        while stack:
            node, parent, path = stack.pop()
            for nb in adj[node]:
                if nb == parent:
                    continue
                if nb in path:
                    # found cycle
                    cycle_len = len(path) - path.index(nb)
                    if cycle_len <= max_len:
                        return True
                elif len(path) < max_len:
                    stack.append((nb, node, path + [nb]))
        # also check if start visited multiple times differently
    return False

def is_4_colorable(edges, n):
    """Check if graph is 4-colorable using simple backtracking"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1]*n
    def backtrack(idx):
        if idx == n:
            return True
        used = set()
        for nb in adj[idx]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(4):
            if c not in used:
                colors[idx] = c
                if backtrack(idx+1):
                    return True
                colors[idx] = -1
        return False
    return backtrack(0)

